<?php
$u=sr_auth('admin');$filter=(string)($_GET['status']??'pending');
if(!in_array($filter,['pending','approved','rejected','all'],true))$filter='pending';
$items=$filter==='all'?sr_all('SELECT j.*,u.name recruiter,u.email FROM jobs j JOIN users u ON u.id=j.recruiter_id ORDER BY j.id DESC LIMIT 300'):sr_all('SELECT j.*,u.name recruiter,u.email FROM jobs j JOIN users u ON u.id=j.recruiter_id WHERE j.status=? ORDER BY j.id DESC LIMIT 300',[$filter]);
sr_page_heading('QUẢN TRỊ HỆ THỐNG','Phê duyệt tin tuyển dụng','Kiểm soát chất lượng tin tuyển dụng được đăng trên nền tảng.');
?><div class="tab-list"><?php foreach(['pending'=>'Chờ duyệt','approved'=>'Đã duyệt','rejected'=>'Từ chối','all'=>'Tất cả'] as $v=>$label):?><a class="tab <?=$filter===$v?'active':''?>" href="<?=sr_url('admin_jobs',['status'=>$v])?>"><?=h($label)?></a><?php endforeach;?></div>
<div class="panel table-panel"><div class="table-responsive"><table><thead><tr><th>Công ty / Vị trí</th><th>Người đăng</th><th>Ngày tạo</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><?php foreach($items as $j):?><tr><td><strong><?=h($j['title'])?></strong><small><?=h($j['company'])?></small><details class="table-details"><summary>Xem mô tả</summary><p><?=h(sr_snip($j['description'],700))?></p><p><b>Kỹ năng:</b> <?=h($j['skills'])?></p></details></td><td><?=h($j['recruiter'])?><small><?=h($j['email'])?></small></td><td><?=h(sr_date($j['created_at']))?></td><td><span class="badge <?=sr_state_class($j['status'])?>"><?=h(sr_status($j['status']))?></span></td><td><div class="table-actions"><?php if($j['status']!=='approved'):?><form method="post"><?=sr_token()?><input type="hidden" name="action" value="job_review"><input type="hidden" name="id" value="<?=$j['id']?>"><input type="hidden" name="status" value="approved"><button class="button primary xs">Duyệt tin</button></form><?php endif;?><?php if($j['status']!=='rejected'):?><form method="post" data-confirm="Từ chối hoặc ẩn tin này?"><?=sr_token()?><input type="hidden" name="action" value="job_review"><input type="hidden" name="id" value="<?=$j['id']?>"><input type="hidden" name="status" value="rejected"><button class="button danger-outline xs">Từ chối</button></form><?php endif;?></div></td></tr><?php endforeach;?><?php if(!$items):?><tr><td colspan="5" class="muted">Không có tin tuyển dụng ở trạng thái này.</td></tr><?php endif;?></tbody></table></div></div>
